function(p) {
  let t = 0;
  let smoothAlpha = 0.5;
  const MAX_RINGS = 14;
  let phases = [];
  p.setup = function() {
    p.createCanvas(400, 400);
    p.colorMode(p.HSB, 360, 100, 100, 100);
    p.noFill();
    for (let i = 0; i < MAX_RINGS; i++) {
      phases.push(i * 0.45);
    }
  };
  p.draw = function() {
    let alphaLevel = p.getParam('alphaLevel');
    if (alphaLevel === undefined || alphaLevel === null || isNaN(alphaLevel)) alphaLevel = 0.5;
    let calmLevel = p.getParam('calmLevel');
    if (calmLevel === undefined || calmLevel === null || isNaN(calmLevel)) calmLevel = 0.5;
    let speed = p.getParam('speed') || 0.012;
    let colorShift = p.getParam('colorShift');
    if (colorShift === undefined || colorShift === null || isNaN(colorShift)) colorShift = 220;
    let ringCount = Math.round(p.getParam('ringCount') || 9);
    ringCount = p.constrain(ringCount, 3, MAX_RINGS);

    smoothAlpha = p.lerp(smoothAlpha, alphaLevel, 0.03);
    t += speed * (1.2 - calmLevel * 0.6);

    p.background((colorShift + 20) % 360, 35, 8 + smoothAlpha * 4, 22);

    let cx = p.width / 2;
    let cy = p.height / 2;
    let maxR = p.min(p.width, p.height) * 0.48;
    let breath = (p.sin(t) + 1) * 0.5;
    let swell = 0.75 + smoothAlpha * 0.35 + breath * (0.08 + smoothAlpha * 0.17);

    for (let i = ringCount - 1; i >= 0; i--) {
      let ratio = (i + 1) / ringCount;
      let localBreath = p.sin(t - phases[i] * (1 - calmLevel * 0.5));
      let r = maxR * ratio * swell * (1 + localBreath * 0.04 * (0.5 + smoothAlpha));
      let hue = (colorShift + ratio * 50 + breath * 15 + 360) % 360;
      let sat = 35 + (1 - calmLevel) * 25 - smoothAlpha * 10;
      let bri = 70 + smoothAlpha * 25;
      let a = (25 + smoothAlpha * 45) * (1.1 - ratio * 0.6);

      p.stroke(hue, sat, bri, a * 0.25);
      p.strokeWeight(8 + smoothAlpha * 10 + calmLevel * 4);
      p.ellipse(cx, cy, r * 2, r * 2);

      p.stroke(hue, sat * 0.8, p.min(100, bri + 5), a);
      p.strokeWeight(1.2 + smoothAlpha * 1.5);
      p.ellipse(cx, cy, r * 2, r * 2);
    }

    p.noStroke();
    let coreR = maxR * (0.12 + breath * 0.06 + smoothAlpha * 0.08);
    for (let k = 4; k > 0; k--) {
      p.fill((colorShift + 10) % 360, 30, 95, (8 + smoothAlpha * 10) / k * 2);
      p.ellipse(cx, cy, coreR * k * 0.8, coreR * k * 0.8);
    }
    p.noFill();
  };
}
